"""Embedded control page for the local Desktop Robot companion."""

PAGE = """<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>Desktop Robot USB</title><style>
:root{color-scheme:dark;font:16px/1.5 system-ui,sans-serif;background:#08131d;color:#edf7fb}*{box-sizing:border-box}body{margin:0;padding:env(safe-area-inset-top) max(16px,env(safe-area-inset-right)) max(24px,env(safe-area-inset-bottom)) max(16px,env(safe-area-inset-left));background:radial-gradient(circle at top,#113450,#08131d 52%);min-height:100vh}main{max-width:760px;margin:auto}.app-header{padding:28px 0 16px}.app-header h1{margin:0;font-size:clamp(1.65rem,5vw,2.35rem);letter-spacing:-.03em}.subtitle{margin:.25rem 0 0;color:#a9c8d9}.status{margin:20px 0 16px;padding:14px 16px;background:#0d2232;border-radius:14px;box-shadow:0 10px 24px #0004;color:#d5f5ff}.tabs{display:flex;gap:8px;overflow-x:auto;padding:4px 2px 12px;scrollbar-color:#4383a1 transparent}.tab{flex:0 0 auto;min-height:44px;padding:.65rem .9rem;border:0;border-radius:10px;background:#102b3e;color:#bcd6e4;font:inherit;font-weight:700;cursor:pointer}.tab[aria-selected=true]{background:#2ed8ff;color:#06202d;box-shadow:0 7px 16px #2ed8ff33}.panel{padding:4px 0 32px}.panel[hidden]{display:none}.section-head{margin:24px 0 10px;font-size:1.15rem}.copy{margin:0 0 16px;color:#b9d0dc}.stack{display:grid;gap:12px}.split{display:grid;gap:12px;grid-template-columns:repeat(2,minmax(0,1fr))}.control{display:grid;gap:6px;color:#c7e0eb;font-weight:650}.control input,.control select{width:100%;min-height:46px;padding:.65rem .75rem;border:1px solid #31566c;border-radius:10px;background:#0b1c29;color:inherit;font:inherit}.checkbox{display:flex;align-items:center;gap:8px;min-height:44px;color:#c7e0eb}.checkbox input{width:18px;height:18px}.actions{display:flex;flex-wrap:wrap;gap:10px}button.action{position:relative;isolation:isolate;min-height:46px;padding:.7rem 1rem;border:0;border-radius:10px;background:#2ed8ff;color:#06202d;font:inherit;font-weight:800;cursor:pointer;transition:transform 130ms cubic-bezier(.16,1,.3,1),box-shadow 180ms ease,background 180ms ease}.action.secondary{background:#183c52;color:#dcf4ff}.action.danger{background:#ff7a86;color:#351018}.action:hover{box-shadow:0 8px 18px #0005}.action:active{transform:translateY(2px) scale(.98)}.action:focus-visible,.tab:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #fff;outline-offset:3px}.action:disabled{cursor:wait;opacity:.78}.action.is-pending{padding-left:2.5rem}.action.is-pending::before{content:"";position:absolute;left:1rem;top:50%;width:13px;height:13px;margin-top:-7px;border:2px solid currentColor;border-right-color:transparent;border-radius:50%;animation:spin .7s linear infinite}.action.is-success{background:#72e3a6;color:#062b18}.action.is-error{background:#ff8e98;color:#351018}@keyframes spin{to{transform:rotate(1turn)}}.message{min-height:1.5em;margin:12px 0 0;color:#bcd6e4}.message[data-kind=success]{color:#92f2bd}.message[data-kind=error]{color:#ffadb4}.firmware-empty{padding:20px;border-radius:14px;background:#102838;color:#c6e1ed}@media(max-width:600px){body{font-size:16px}.app-header{padding-top:20px}.split{grid-template-columns:1fr}.actions{display:grid;grid-template-columns:1fr}.action{width:100%}.tabs{margin-right:-16px;padding-right:16px}}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;scroll-behavior:auto!important;transition-duration:.01ms!important}}
</style><main><header class="app-header"><h1>Desktop Robot</h1><p class="subtitle">Điều khiển trực tiếp qua USB</p><p class="status" id="status" aria-live="polite">Đang đọc trạng thái…</p></header>
<nav class="tabs" role="tablist" aria-label="Chức năng điều khiển"><button class="tab" id="tab-overview" role="tab" aria-controls="panel-overview" aria-selected="true" data-tab="overview">Tổng quan</button><button class="tab" id="tab-display" role="tab" aria-controls="panel-display" aria-selected="false" data-tab="display">Màn hình</button><button class="tab" id="tab-gifs" role="tab" aria-controls="panel-gifs" aria-selected="false" data-tab="gifs">GIF</button><button class="tab" id="tab-weather" role="tab" aria-controls="panel-weather" aria-selected="false" data-tab="weather">Thời tiết</button><button class="tab" id="tab-firmware" role="tab" aria-controls="panel-firmware" aria-selected="false" data-tab="firmware">Firmware</button></nav>
<section class="panel" id="panel-overview" role="tabpanel" aria-labelledby="tab-overview"><h2 class="section-head">Kết nối</h2><p class="copy">Nếu robot vừa được cắm lại, kết nối lại USB rồi tiếp tục điều khiển.</p><div class="actions"><button class="action" onclick="send('/api/connect',{},this)">Kết nối lại USB</button></div></section>
<section class="panel" id="panel-display" role="tabpanel" aria-labelledby="tab-display" hidden><h2 class="section-head">Nội dung hiển thị</h2><div class="actions"><button class="action" onclick="send('/api/screen',{screen:1},this)">Khuôn mặt</button><button class="action secondary" onclick="send('/api/screen',{screen:2},this)">Thời tiết</button><button class="action secondary" onclick="send('/api/screen',{screen:3},this)">Cảm biến</button></div><h2 class="section-head">Biểu cảm</h2><div class="split"><label class="control">Chọn biểu cảm<select id="animation"><option value="0">Idle</option><option value="1">Blink</option><option value="2">Happy</option><option value="3">Sleepy</option><option value="4">Surprised</option><option value="5">Look left</option><option value="6">Look right</option><option value="7">Sunny</option><option value="8">Rain</option></select></label><div class="actions"><button class="action" onclick="send('/api/animation',{animation:+document.querySelector('#animation').value},this)">Hiển thị biểu cảm</button></div></div></section>
<section class="panel" id="panel-gifs" role="tabpanel" aria-labelledby="tab-gifs" hidden><h2 class="section-head">Nhập GIF</h2><p class="copy">Chọn ô GIF, nhập tệp rồi nạp trực tiếp vào robot.</p><div class="stack"><label class="control">Ô GIF<select id="gifSlot"></select></label><label class="control">Tệp GIF<input id="gifFile" type="file" accept="image/gif"></label><div class="actions"><button class="action" onclick="upload(this)">Nhập và nạp GIF</button><button class="action danger" onclick="if(confirm('Xóa GIF ở ô đang chọn?'))send('/api/gif/delete',{slot:+document.querySelector('#gifSlot').value},this)">Xóa GIF</button><button class="action secondary" onclick="send('/api/animation',{animation:+document.querySelector('#gifSlot').value},this)">Hiển thị GIF</button></div></div></section>
<section class="panel" id="panel-weather" role="tabpanel" aria-labelledby="tab-weather" hidden><h2 class="section-head">Wi-Fi</h2><div class="stack"><label class="control">Tên Wi-Fi<input id="ssid" placeholder="Tên Wi-Fi"></label><label class="control">Mật khẩu<input id="password" type="password" placeholder="Mật khẩu"></label><label class="checkbox"><input id="openNetwork" type="checkbox">Mạng mở, không mật khẩu</label><div class="actions"><button class="action" onclick="send('/api/wifi',{ssid:document.querySelector('#ssid').value,password:document.querySelector('#password').value,open_network:document.querySelector('#openNetwork').checked},this)">Lưu Wi-Fi</button></div></div><h2 class="section-head">Vị trí thời tiết</h2><div class="split"><label class="control">Vĩ độ<input id="latitude" placeholder="10.8231"></label><label class="control">Kinh độ<input id="longitude" placeholder="106.6297"></label><label class="control">Múi giờ<input id="timezone" placeholder="Asia/Ho_Chi_Minh"></label><label class="control">Cập nhật (phút)<input id="interval" type="number" min="5" max="180" value="15"></label></div><div class="actions"><button class="action" onclick="send('/api/weather',{latitude:document.querySelector('#latitude').value,longitude:document.querySelector('#longitude').value,timezone:document.querySelector('#timezone').value,interval:+document.querySelector('#interval').value},this)">Lưu vị trí</button></div></section>
<section class="panel" id="panel-firmware" role="tabpanel" aria-labelledby="tab-firmware" hidden><div id="firmware"><h2 class="section-head">Firmware</h2><p class="copy">Ứng dụng sẽ sao lưu thư viện GIF trước khi nạp. Giữ cáp USB kết nối trong toàn bộ quá trình.</p><div class="actions"><button class="action secondary" onclick="send('/api/firmware/build',{},this)">Build firmware</button><button class="action" onclick="if(confirm('Build và nạp firmware qua USB?'))send('/api/firmware/flash',{},this)">Build và nạp</button></div></div></section>
<p class="message" id="message" aria-live="polite"></p></main><script>
const token='__TOKEN__',tabs=[...document.querySelectorAll('[role=tab]')],panels=[...document.querySelectorAll('[role=tabpanel]')];
for(let i=1;i<=32;i++){const o=document.createElement('option');o.value=i+8;o.textContent=`GIF ${String(i).padStart(2,'0')}`;gifSlot.append(o)}
function activateTab(name,focus=false){if(!tabs.some(t=>t.dataset.tab===name))name='overview';tabs.forEach(tab=>{const active=tab.dataset.tab===name;tab.setAttribute('aria-selected',active);tab.tabIndex=active?0:-1;if(active&&focus)tab.focus()});panels.forEach(panel=>panel.hidden=panel.id!==`panel-${name}`)}
function selectTab(name,focus=false){location.hash=name;activateTab(name,focus)}
tabs.forEach((tab,index)=>{tab.onclick=()=>selectTab(tab.dataset.tab);tab.onkeydown=e=>{let next=index;if(e.key==='ArrowRight')next=(index+1)%tabs.length;else if(e.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;else return;e.preventDefault();selectTab(tabs[next].dataset.tab,true)}});addEventListener('hashchange',()=>activateTab(location.hash.slice(1)));activateTab(location.hash.slice(1));
function message(text,kind=''){const el=document.querySelector('#message');el.textContent=text;el.dataset.kind=kind}async function call(path,data){const r=await fetch(path,{method:data?'POST':'GET',headers:{'X-Robot-Token':token,'Content-Type':'application/json'},body:data?JSON.stringify(data):undefined});const j=await r.json();if(!r.ok)throw Error(j.error);return j}
async function runAction(button,pendingLabel,action){if(!button||button.disabled)return;const label=button.dataset.label||button.textContent;button.dataset.label=label;button.disabled=true;button.setAttribute('aria-busy','true');button.classList.remove('is-success','is-error');button.classList.add('is-pending');button.textContent=pendingLabel;try{const result=await action();button.classList.replace('is-pending','is-success');message('Đã gửi lệnh','success');return result}catch(error){button.classList.replace('is-pending','is-error');message(error.message,'error');throw error}finally{setTimeout(()=>{button.disabled=false;button.setAttribute('aria-busy','false');button.classList.remove('is-pending','is-success','is-error');button.textContent=label},900)}}
async function send(path,data,button){try{return await runAction(button,'Đang gửi…',async()=>{const result=await call(path,data);await refresh();return result})}catch(error){return null}}async function upload(button){const file=gifFile.files[0];if(!file){message('Hãy chọn tệp GIF','error');return}try{return await runAction(button,'Đang nạp GIF…',async()=>{const r=await fetch('/api/gif/upload?slot='+gifSlot.value,{method:'POST',headers:{'X-Robot-Token':token},body:file});const j=await r.json();if(!r.ok)throw Error(j.error);message(`Đã nạp ${j.slot} (${j.bytes} byte)`,'success');return j})}catch(error){return null}}
async function refresh(){try{const s=await call('/api/status');status.textContent=`Màn hình ${s.screen}; biểu cảm ${s.animation}; Wi-Fi ${s.network}; nhiệt độ ${s.temperature??'—'} °C; độ ẩm ${s.humidity??'—'} %`}catch(error){status.textContent=error.message}}async function load(){try{const s=await call('/api/settings');for(const id of ['ssid','latitude','longitude','timezone'])document.getElementById(id).value=s[id];interval.value=s.weather_interval}catch(error){message(error.message,'error')}}if(!__FIRMWARE_AVAILABLE__)firmware.innerHTML='<div class="firmware-empty">Chưa có bộ công cụ build đi kèm. Hãy dùng bản phân phối đầy đủ để build hoặc nạp firmware.</div>';refresh();load();setInterval(refresh,5000)
</script></html>"""

PAGE = PAGE.replace(">Khuôn mặt</button>", ">Biểu cảm liên tục</button>")
PAGE = PAGE.replace("Chọn ô GIF, nhập tệp rồi nạp trực tiếp vào robot.",
                    "GIF đã chọn sẽ lặp liên tục; không tự chuyển sang biểu cảm hoặc thời tiết.")
PAGE = PAGE.replace("</main><script>", """<section class="log-panel" aria-label="Nhật ký chẩn đoán"><h2>Nhật ký thao tác</h2><ol class="log-list" id="clientLog" aria-live="polite"></ol><h2>Nhật ký bridge USB</h2><ol class="log-list" id="serverLog" aria-live="polite"></ol></section></main><script>""")
PAGE = PAGE.replace("</style>", """.log-panel{margin-top:20px;padding:14px 16px;background:#0d2232;border-radius:14px}.log-panel h2{margin:0 0 8px;font-size:1rem}.log-list{max-height:180px;overflow:auto;margin:0;padding-left:1.25rem;color:#bcd6e4;font:13px/1.45 ui-monospace,monospace}.log-list li[data-outcome=error]{color:#ffadb4}.log-list li[data-outcome=ok]{color:#92f2bd}</style>""")
PAGE = PAGE.replace("</section></main><script>", "</section></main><script>const status=document.querySelector('#status');</script><script>")
PAGE += """<script>
const clientEvents=[];
function recordClientEvent(action,outcome,detail=''){clientEvents.unshift({time:new Date().toLocaleTimeString(),action,outcome,detail});clientEvents.splice(100);renderLog(clientLog,clientEvents)}
function renderLog(element,events){element.replaceChildren(...events.map(event=>{const item=document.createElement('li');item.dataset.outcome=event.outcome;item.textContent=`${event.time} · ${event.action} · ${event.outcome}${event.detail?`: ${event.detail}`:''}`;return item}))}
async function refreshLogs(){try{const data=await call('/api/log');renderLog(serverLog,data.events)}catch(error){recordClientEvent('bridge log','error',error.message)}}
async function refresh(){try{const s=await call('/api/status');status.textContent=`Màn hình ${s.screen}; biểu cảm ${s.animation}; Wi-Fi ${s.network}; nhiệt độ ${s.temperature??'—'} °C; độ ẩm ${s.humidity??'—'} %`}catch(error){status.textContent=`Chưa đọc được trạng thái mới: ${error.message}`;recordClientEvent('status','error',error.message)}}
async function send(path,data,button){try{const result=await runAction(button,'Đang gửi…',()=>call(path,data));recordClientEvent(path,'ok','Lệnh đã được robot xác nhận');void refresh().catch(error=>recordClientEvent('status','error',error.message));void refreshLogs();return result}catch(error){recordClientEvent(path,'error',error.message);return null}}
async function upload(button){const file=gifFile.files[0];if(!file){message('Hãy chọn tệp GIF','error');recordClientEvent('gif upload','error','Chưa chọn tệp');return null}try{recordClientEvent('gif upload','started',`${file.name} (${file.size} byte)`);const result=await runAction(button,'Đang nạp GIF…',async()=>{const r=await fetch('/api/gif/upload?slot='+gifSlot.value,{method:'POST',headers:{'X-Robot-Token':token},body:file});const j=await r.json();if(!r.ok)throw Error(j.error);return j});recordClientEvent('gif upload','ok',`${result.slot} (${result.bytes} byte)`);void refreshLogs();return result}catch(error){recordClientEvent('gif upload','error',error.message);void refreshLogs();return null}}
refreshLogs();setInterval(refreshLogs,5000);
</script>"""
